UPDATE effect SET effectDescription =
  'TEMP/TEST DATA - real min level TBD. Damage Reduction 5, bypassed by the appropriate material. Renamed from ''Damage Reduction (Adamantine)'' 2026-07-28 - Adamantine is just one delivery mechanism for this effect, not part of the effect''s identity (per Jeff: ''Adamantine'' on armor is best thought of as granting the DR effect - the material itself is the middleman, not relevant to what gets selected).'
WHERE effectName = 'Damage Reduction';
